            "第二步：求二階導函數：$f''(x) = \\frac{d}{dx}(3x^2 - 6x - 9) = 6x - 6 = 6(x - 1)$",
            "第三步：解 $f'(x) = 0$ 得臨界點：$x = -1$ 與 $x = 3$",
